        /// <summary>把字符串数组解析成点序列。返回 null 表示数据损坏。</summary>
        public static List<Point[]> Parse(string[] source)
        {
            if (source == null) return null;
            var result = new List<Point[]>(source.Length);
            foreach (string line in source)
            {
                string[] tokens = line.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                if (tokens.Length < 3) return null;
                var pts = new Point[tokens.Length];
                for (int i = 0; i < tokens.Length; i++)
                {
                    int comma = tokens[i].IndexOf(',');
                    if (comma <= 0 || comma >= tokens[i].Length - 1) return null;
                    double x, y;
                    if (!double.TryParse(tokens[i].Substring(0, comma), NumberStyles.Float,
                            CultureInfo.InvariantCulture, out x)) return null;
                    if (!double.TryParse(tokens[i].Substring(comma + 1), NumberStyles.Float,
                            CultureInfo.InvariantCulture, out y)) return null;
                    pts[i] = new Point(x, y);
                }
                result.Add(pts);
            }
            return result;
        }
    }
